-- ---------- 예제 : 물리 모델 (같은 이름이 이미 있으면 넣지 않는다) ----------
insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL, 0, s.SCHM_SN, 'TB_AI_PRVDR', 'AI 제공자', 'Lexorma 가 호출하는 AI 서버(Provider) 설정 (AI-3). 시스템 관리자만 관리하고, 연결은 외부 연결 허용 규칙(AI_HTTP)이 열어야 한다', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_AI_PRVDR');
